screens.harness=() => {
  const h=S.har,x=HAR_SNAPSHOT,view=['overview','runtime','adapters','containers','cmds'].includes(h.tab) ? h.tab : 'overview';
  const summary=`<section class="panel har-summary" aria-label="Сводка Harness"><div class="har-metrics">${[['Версия в снимке',S.empty ? '—' : x.version,'Установка проекта'],['Rust runtime',S.empty ? '—' : x.runtime,'Схема '+x.store.schema],['Навыки',S.empty ? '—' : x.skills,S.empty ? 'Нет данных' : '1 расхождение'],['Audit',S.empty ? '—' : x.store.audit,S.empty ? 'Нет данных' : 'Цепочка цела']].map(([name,value,detail]) => `<div><span>${name}</span><b>${value}</b><small>${S.empty ? 'Нет данных' : detail}</small></div>`).join('')}</div><div class="har-summary-foot"><span class="${S.empty ? '' : 'err'}">${ic(S.empty ? 'dot' : 'alert','sm')} ${S.empty ? 'Нет данных об установке' : CHECKS.filter((c) => c.area === 'Файлы Harness' && c.s === 'err').length+' ошибки файлов Harness'}</span><span>${S.empty ? 'Нет данных об адаптерах' : HAR_ADAPTERS.length+' адаптера · '+HAR_ADAPTERS.filter((a) => a.state === 'warn').length+' с ограничениями'}</span><span class="rep-caption">${ic('clock','sm')} ${S.empty ? 'Нет данных' : S.conn === 'reconnect' ? 'Кэш 22:01 · устарел' : 'Снимок 22:01'} · демо</span></div></section>`;
  const nav=`<div class="har-tabs">${pipeTabs('har.tab',[['overview','Обзор','1'],['runtime','Runtime',ic('cpu','sm')],['adapters','Адаптеры',HAR_ADAPTERS.length],['containers','Контейнеры',ic('box','sm')],['cmds','Команды',HARNESS_CMDS.length]],view)}</div>`;
  const content=S.empty ? `<section class="panel har-empty">${empty('Нет данных об установке Harness','Откройте проект и проверьте состав и готовность установки.',btn('Открыть проект','go:open-project',{cls:'sm primary',icon:'project'}))}</section>` : {overview:harOverview,runtime:harRuntime,adapters:harAdapters,containers:harContainers,cmds:harCommands}[view]();
  return `<div class="page harness-screen fit">${head('Harness','Установка, runtime и инфраструктура проекта.',btn('','har-refresh',{cls:'icon',icon:'refresh',title:'Обновить состояние Harness',dis:S.empty || S.conn !== 'online',data:'aria-label="Обновить состояние Harness"'})+btn('Диагностика','go:diagnostics',{cls:'sm',icon:'health'}))}${summary}${nav}${content}</div>`.replaceAll('data-act="set"','data-act="har-set"');
};
Object.assign(actions,{
  'har-set':(_,el) => {const key=el.dataset.k,value=el.dataset.v;setPath(key,value);render();const target=$(`[data-k="${key}"][data-v="${value}"]`);if(target) target.focus();},
  'har-refresh':() => {if(S.empty || S.conn !== 'online') return;render();toast('Демонстрационный снимок Harness обновлён');},
  'har-check':(id) => {Object.assign(S.diag,{tab:'checks',filter:'all',area:'all',q:'',sel:id,dtab:'info'});actions.go('diagnostics');},
  'har-feature':(id) => {S.diag.tab='feat';Object.assign(S.feat,{filter:'all',cat:'all',q:'',sel:id});actions.go('diagnostics');},
  'har-adapter':(id) => {Object.assign(S.har,{tab:'adapters',adapter:id,adapterQ:''});render();},
  'har-adapter-pick':(id) => {S.har.adapter=id;render();const target=$(`[data-act="har-adapter-pick:${id}"]`);if(target) target.focus();},
  'har-adapter-reset':() => {S.har.adapterQ='';render();},
  'har-activity':(name) => {const r=RUNS.find((r) => r.agent === name && r.state !== 'done');Object.assign(S.act,{sel:r ? r.id : '#716',status:'all',role:'all',q:'',tab:'overview',side:'source'});actions.go('agent-activity');},
  'har-container':(key) => {Object.assign(S.orch,{q:'',role:'all',status:'all',stage:'all',result:'all',scope:'all'});actions['orch-container'](key);actions.go('orchestration');},
  'har-containers-reset':() => {S.har.containerFilter='all';render();},
  'har-command':(id) => {Object.assign(S.har,{tab:'cmds',command:id,commandQ:'',commandMode:'all'});render();},
  'har-command-pick':(id) => {S.har.command=id;render();const target=$(`[data-act="har-command-pick:${id}"]`);if(target) target.focus();},
  'har-command-reset':() => {Object.assign(S.har,{commandQ:'',commandMode:'all'});render();},
  'har-copy-command':async (id) => {const c=HARNESS_CMDS[Number(id)];if(!c || S.empty) return;try{await navigator.clipboard.writeText(c[0]);toast('Команда скопирована');}catch{toast('Не удалось скопировать. Выделите команду вручную.');}},
  'har-command-route':(id) => {if(id === '3' || id === '5'){S.har.tab=id === '3' ? 'containers' : 'runtime';render();return;}actions.go(({0:'diagnostics',1:'update-harness',2:'update-harness',4:'repo-map'})[id] || 'harness');},
});

/* ---------- Repo Map ---------- */
const RM_SNAPSHOT={tier:'full',parser:'tree-sitter',generation:12,head:'47d465ce',files:1284,symbols:7842,relations:3912,tokens:'≈184k'};
const rmFiles=() => [...new Set([...SYMBOLS.map((s) => `${s.mod}/${s.file}`),...REPO_TREE.flatMap(([root,,kids]) => kids.filter(([name]) => !name.endsWith('/')).map(([name]) => root+name))])].sort().map((path) => ({path,mod:MODULES.find((m) => path.startsWith(m.id+'/'))?.id || '',name:path.split('/').pop()}));
const rmFileSymbols=(file) => SYMBOLS.filter((s) => `${s.mod}/${s.file}` === file.path);
const rmRoot=(path) => MODULES.find((m) => path === m.id || path.startsWith(m.id+'/'))?.id;
const rmSnippet=(file) => file.path === 'native/harness-runtime/src/lib.rs' ? {start:61,lines:FILE_VIEW} : null;
function rmData() {
  const r=S.repo,q=(r.q || '').trim().toLowerCase();r.kind ||= 'all';r.relType ||= 'all';
  return {files:rmFiles().filter((f) => (r.mod === 'all' || f.mod === r.mod) && (!q || f.path.toLowerCase().includes(q))),symbols:SYMBOLS.filter((s) => (r.mod === 'all' || s.mod === r.mod) && (r.kind === 'all' || s.kind === r.kind) && (!q || `${s.n} ${s.mod}/${s.file} ${s.sig}`.toLowerCase().includes(q))),links:REL.map(([from,to,type,count],id) => ({from,to,type,count,id})).filter((l) => (r.mod === 'all' || rmRoot(l.from) === r.mod || rmRoot(l.to) === r.mod) && (r.relType === 'all' || l.type === r.relType) && (!q || `${l.from} ${l.to} ${l.type}`.toLowerCase().includes(q)))};
}
const rmNoResult=(title,detail) => `<section class="panel rm-empty">${empty(title,detail,btn('Сбросить фильтры','rm-reset',{cls:'sm'}))}</section>`;
function rmCode(file) {
  const snippet=rmSnippet(file),line=Number(S.repo.line);
  return snippet ? `<div class="rm-code-head"><span>Фрагмент · строки ${snippet.start}–${snippet.start+snippet.lines.length-1}</span><span>Только чтение</span></div><div class="rm-code" role="region" tabindex="0" aria-label="Код ${esc(file.name)}">${snippet.lines.map((text,i) => `<div class="${line === snippet.start+i ? 'highlight' : ''}"><span>${snippet.start+i}</span><code>${esc(text)}</code></div>`).join('')}</div>${line && (line < snippet.start || line >= snippet.start+snippet.lines.length) ? `<p class="rm-context-note">Строка ${line} находится за пределами переданного фрагмента.</p>` : ''}` : `<div class="rm-code-missing">${ic('file')}<div><h3>Содержимое файла не передано</h3><p>Доступны путь и сведения из фрагмента индекса. Откройте вкладку «Символы файла», чтобы посмотреть доступные объявления.</p></div></div>`;
}
function rmFileDetail(file) {
  const syms=rmFileSymbols(file),side=['code','symbols'].includes(S.repo.fileTab) ? S.repo.fileTab : 'code';
  return `<section class="panel rm-detail" aria-label="Файл ${esc(file.path)}"><div class="rm-detail-head">${ic('file')}<div><h2>${esc(file.name)}</h2><p class="mono clamp1" title="${esc(file.path)}">${esc(file.path)}</p></div><span class="tag">${file.name.endsWith('.rs') ? 'Rust' : 'Python'}</span></div>${tabs('repo.fileTab',[['code','Код'],['symbols',`Символы файла · ${syms.length}`]],side)}<div class="rm-file-content">${side === 'code' ? rmCode(file) : syms.length ? `<ul class="rm-file-symbols">${syms.map((s) => `<li><button data-act="rm-open-symbol:${SYMBOLS.indexOf(s)}">${ic(s.kind === 'class' ? 'box' : 'edit','sm')}<span><b class="mono clamp1" title="${esc(s.n)}">${esc(s.n)}</b><small>Строка ${s.line} · ${s.used.length} ${plural(s.used.length,'место','места','мест')} использования</small></span><span class="tag">${s.kind}</span>${ic('chev','sm')}</button></li>`).join('')}</ul>` : '<p class="rm-context-note">Объявления для этого файла во фрагменте индекса отсутствуют.</p>'}</div><div class="rm-file-foot"><span>Фрагмент индекса · HEAD ${RM_SNAPSHOT.head}</span><div>${btn('Путь','rm-copy:'+file.path,{cls:'sm',icon:'copy',title:'Скопировать путь файла'})}${btn('Открыть просмотр','rm-file-preview:'+file.path,{cls:'sm',icon:'eye'})}</div></div></section>`;
}
function rmOverview(data) {
  const r=S.repo,q=r.q.trim(),roots=MODULES.filter((m) => r.mod === 'all' || r.mod === m.id),file=data.files.find((f) => f.path === r.file) || data.files[0];if(file) r.file=file.path;
  if(q && !data.files.length) return rmNoResult('Файлы не найдены','Измените запрос или выберите другой модуль.');
  const tree=`<aside class="panel rm-tree" aria-label="Модули и файлы"><div class="ph"><h2>Модули · ${roots.length}</h2><span class="rep-caption">Файлы в снимке</span></div><div class="rm-tree-scroll">${roots.filter((m) => !q || data.files.some((f) => f.mod === m.id)).map((m) => {const files=data.files.filter((f) => f.mod === m.id);return `<section><button class="rm-root ${r.mod === m.id ? 'selected' : ''}" data-act="rm-module:${m.id}" title="Открыть модуль ${m.id}">${ic('folder','sm')}<b class="mono clamp1">${m.id}/</b><span>${m.n}</span></button>${files.length ? `<ul>${files.map((f) => `<li><button class="rm-file ${file && file.path === f.path ? 'selected' : ''}" data-act="rm-file:${f.path}" aria-pressed="${!!file && file.path === f.path}">${ic('file','sm')}<span class="mono clamp1" title="${esc(f.path)}">${esc(f.path.slice(m.id.length+1))}</span></button></li>`).join('')}</ul>` : '<p class="rm-tree-note">Подробный список не передан.</p>'}</section>`;}).join('')}</div><div class="rm-tree-foot">${data.files.length} файлов с метаданными · фрагмент</div></aside>`;
  return `<div class="rm-workspace">${tree}${file ? rmFileDetail(file) : `<section class="panel rm-detail rm-unavailable">${empty('Подробности модуля не переданы',`В снимке модуля ${esc(r.mod)} есть ${MODULES.find((m) => m.id === r.mod)?.n || 0} файлов. Список файлов и их код в макете отсутствуют.`,btn('Все модули','rm-reset',{cls:'sm'}))}</section>`}</div>`;
}
function rmSymbols(data) {
  const r=S.repo,sel=data.symbols.find((s) => s.n === r.sel) || data.symbols[0];if(!sel) return rmNoResult('Символы не найдены','Измените имя, путь, тип или модуль. Во фрагменте доступны пять объявлений.');r.sel=sel.n;
  const left=`<aside class="panel rm-symbol-list" aria-label="Список символов"><div class="ph"><h2>Символы · ${data.symbols.length}</h2><span class="rep-caption">Фрагмент индекса</span></div><div class="rm-list-scroll">${data.symbols.map((s) => `<button class="rm-symbol-choice ${s.n === sel.n ? 'selected' : ''}" data-act="rm-select-symbol:${SYMBOLS.indexOf(s)}" aria-pressed="${s.n === sel.n}">${ic(s.kind === 'class' ? 'box' : 'edit','sm')}<span><b class="mono clamp1" title="${esc(s.n)}">${esc(s.n)}</b><small class="mono clamp1" title="${esc(s.mod+'/'+s.file)}">${esc(s.mod+'/'+s.file)}:${s.line}</small></span><span class="tag">${s.kind}</span></button>`).join('')}</div></aside>`;
  const id=SYMBOLS.indexOf(sel),right=`<section class="panel rm-detail" aria-label="Символ ${esc(sel.n)}"><div class="rm-detail-head">${ic(sel.kind === 'class' ? 'box' : 'edit')}<div><h2 class="mono clamp1" title="${esc(sel.n)}">${esc(sel.n)}</h2><p class="mono clamp1" title="${esc(sel.mod+'/'+sel.file)}">${esc(sel.mod+'/'+sel.file)}:${sel.line}</p></div><span class="tag">${sel.kind}</span></div><div class="rm-symbol-body"><div class="rm-section-heading"><h3>Объявление</h3><span>Строка ${sel.line}</span></div><pre class="rm-signature"><code>${esc(sel.sig)}</code></pre><div class="rm-section-heading"><h3>Используется · ${sel.used.length}</h3><span>Места из фрагмента</span></div><ul class="rm-usages">${sel.used.map((u,i) => `<li><button data-act="rm-reference:${id}|${i}">${ic('link','sm')}<span class="mono">${esc(u)}</span>${ic('chev','sm')}</button></li>`).join('')}</ul></div><div class="rm-file-foot"><span>HEAD индекса · ${RM_SNAPSHOT.head}</span><div>${btn('Сигнатура','rm-copy:'+sel.sig,{cls:'sm',icon:'copy'})}${btn('Перейти к файлу','rm-symbol-file:'+id,{cls:'sm primary',icon:'file'})}</div></div></section>`;
  return `<div class="rm-workspace rm-symbol-workspace">${left}${right}</div>`;
}
function rmLinks(data) {
  const r=S.repo,sel=data.links.find((l) => String(l.id) === String(r.link)) || data.links[0];if(!sel) return rmNoResult('Связи не найдены','Измените запрос, модуль или тип связи.');r.link=String(sel.id);
  const left=`<section><div class="ph"><h2>Связи модулей · ${data.links.length}</h2><span class="rep-caption">Фрагмент индекса</span></div><div class="rm-rel-heading"><span>Направление</span><span>Тип</span><span>Связей</span></div><ul class="rm-rel-list">${data.links.map((l) => `<li><button class="${l.id === sel.id ? 'selected' : ''}" data-act="rm-select-link:${l.id}" aria-pressed="${l.id === sel.id}"><span class="rm-rel-path"><b class="mono clamp1" title="${l.from}">${l.from}</b><small class="mono clamp1" title="${l.to}">→ ${l.to}</small></span><span class="tag">${l.type}</span><b>${l.count}</b></button></li>`).join('')}</ul></section>`;
  const right=`<section><div class="ph"><h2>Выбранная связь</h2>${pill('info',sel.type)}</div><div class="rm-link-body"><div class="rm-link-route"><span><small>Откуда</small><b class="mono">${sel.from}</b></span>${ic('chev')}<span><small>Куда</small><b class="mono">${sel.to}</b></span></div><dl class="har-kv"><dt>Тип</dt><dd>${{ipc:'IPC · взаимодействие процессов',import:'Импорт модуля',storage:'Обращение к хранилищу'}[sel.type]}</dd><dt>Связей в снимке</dt><dd>${sel.count}</dd></dl><div class="rm-link-actions">${[sel.from,sel.to].map((path,i) => rmRoot(path) ? btn(i ? 'Символы назначения' : 'Символы источника','rm-related:'+path,{cls:'sm',icon:'edit'}) : `<span class="rep-caption">${esc(path)} — вне списка модулей</span>`).join('')}</div><p class="rm-context-note">Число связей взято из снимка. Список отдельных обращений этой связи не передан.</p></div></section>`;
  return `<div class="panel rm-link-pair">${left}${right}</div>`;
}
screens['repo-map']=() => {
  const r=S.repo,x=RM_SNAPSHOT;r.q ||= '';r.mod ||= 'all';r.file ||= 'native/harness-runtime/src/lib.rs';const view=['overview','symbols','links'].includes(r.tab) ? r.tab : 'overview',data=rmData();
  const summary=`<section class="panel rm-summary" aria-label="Сводка индекса"><div class="rm-metrics">${[['Файлы',x.files.toLocaleString('ru-RU')],['Символы',x.symbols.toLocaleString('ru-RU')],['Связи',x.relations.toLocaleString('ru-RU')],['Токены',x.tokens]].map(([label,n]) => `<div><span>${label}</span><b>${S.empty ? '—' : n}</b></div>`).join('')}</div><div class="rm-snapshot-meta"><span>${ic('db','sm')} Tier <b>${S.empty ? '—' : x.tier}</b></span><span>Parser <b>${S.empty ? '—' : x.parser}</b></span><span>Generation <b>${S.empty ? '—' : x.generation}</b></span><span>HEAD индекса <b class="mono">${S.empty ? '—' : x.head}</b></span><span class="rep-caption">${ic('clock','sm')} ${S.empty ? 'Нет данных' : S.conn === 'reconnect' ? 'Кэш 22:01 · устарел' : 'Снимок 22:01'} · демо</span></div></section>`;
  const nav=`<div class="rm-tabs">${pipeTabs('repo.tab',[['overview','Файлы',ic('folder','sm')],['symbols','Символы',S.empty ? '—' : SYMBOLS.length],['links','Связи',S.empty ? '—' : REL.length]],view)}</div>`;
  const filter= view === 'symbols' ? `<label class="field"><span class="sr">Тип символа</span><select data-bind="repo.kind">${[['all','Любой тип'],['fn','Функции'],['class','Классы']].map(([v,l]) => `<option value="${v}" ${r.kind === v ? 'selected' : ''}>${l}</option>`).join('')}</select></label>` : view === 'links' ? `<label class="field"><span class="sr">Тип связи</span><select data-bind="repo.relType">${[['all','Все связи'],['import','Import'],['ipc','IPC'],['storage','Storage']].map(([v,l]) => `<option value="${v}" ${r.relType === v ? 'selected' : ''}>${l}</option>`).join('')}</select></label>` : '';
  const current=view === 'overview' ? data.files : view === 'symbols' ? data.symbols : data.links;
  const toolbar=`<div class="panel rm-toolbar">${search('repo.q',r.q,view === 'overview' ? 'Поиск файла или пути' : view === 'symbols' ? 'Поиск символа, пути или сигнатуры' : 'Поиск модуля или связи')}<label class="field"><span class="sr">Модуль Repo Map</span><select data-bind="repo.mod"><option value="all">Все модули</option>${MODULES.map((m) => `<option ${m.id === r.mod ? 'selected' : ''}>${m.id}</option>`).join('')}</select></label>${filter}${btn('Сбросить','rm-reset',{cls:'sm ghost',dis:!r.q && r.mod === 'all' && (view !== 'symbols' || r.kind === 'all') && (view !== 'links' || r.relType === 'all')})}</div>`;
  const body=S.empty ? `<section class="panel rm-empty">${empty('Нет данных индекса','Откройте проект и проверьте состояние Repo Map.',btn('Открыть проект','go:open-project',{cls:'sm primary',icon:'project'}))}</section>` : {overview:rmOverview,symbols:rmSymbols,links:rmLinks}[view](data);
  return `<div class="page repo-map-screen fit">${head('Repo Map','Файлы, объявления и зависимости проекта.',btn('Экспорт фрагмента','rm-export',{cls:'sm',icon:'file',dis:S.empty || !current.length})+btn('','rm-refresh',{cls:'icon',icon:'refresh',dis:S.empty || S.conn !== 'online',title:'Обновить снимок индекса',data:'aria-label="Обновить снимок индекса"'}))}${summary}${nav}${S.empty ? '' : toolbar}${body}${S.empty ? '' : `<p class="rm-scope-note">${ic('help','sm')} Счётчики — весь демо-снимок. Для просмотра переданы ${rmFiles().length} файлов, ${SYMBOLS.length} символов и ${REL.length} примеров связей. Текущий HEAD не передан: свежесть индекса не подтверждена.</p>`}</div>`.replaceAll('data-act="set"','data-act="rm-set"');
};
function rmChooseFile(path,line=null) {const f=rmFiles().find((f) => f.path === path);if(!f) return;Object.assign(S.repo,{tab:'overview',file:path,fileTab:'code',mod:f.mod,q:'',line});render();}
Object.assign(actions,{
  'rm-set':(_,el) => {const key=el.dataset.k,value=el.dataset.v;setPath(key,value);render();const target=$(`[data-k="${key}"][data-v="${value}"]`);if(target) target.focus();},
  'rm-reset':() => {Object.assign(S.repo,{q:'',mod:'all',kind:'all',relType:'all',line:null});render();},
  'rm-module':(mod) => {Object.assign(S.repo,{mod,q:'',line:null});render();},
  'rm-file':(path) => {S.repo.file=path;S.repo.line=null;render();const target=$(`[data-act="rm-file:${path}"]`);if(target) target.focus();},
  'rm-open-symbol':(id) => {const s=SYMBOLS[Number(id)];if(!s) return;Object.assign(S.repo,{tab:'symbols',sel:s.n,mod:s.mod,q:'',kind:'all'});render();},
  'rm-select-symbol':(id) => {const s=SYMBOLS[Number(id)];if(!s) return;S.repo.sel=s.n;render();const target=$(`[data-act="rm-select-symbol:${id}"]`);if(target) target.focus();},
  'rm-symbol-file':(id) => {const s=SYMBOLS[Number(id)];if(s) rmChooseFile(`${s.mod}/${s.file}`,s.line);},
  'rm-select-link':(id) => {S.repo.link=id;render();const target=$(`[data-act="rm-select-link:${id}"]`);if(target) target.focus();},
  'rm-related':(path) => {const mod=rmRoot(path);if(!mod) return;Object.assign(S.repo,{tab:'symbols',mod,q:path,kind:'all'});render();},
  'repo-mod':(path,el) => actions['rm-related'](el?.dataset.v || path || 'harness'),
  'rm-refresh':() => {if(S.empty || S.conn !== 'online') return;render();toast('Демонстрационный снимок Repo Map обновлён');},
  'rm-file-preview':(path) => {const file=rmFiles().find((f) => f.path === path);if(!file || S.empty) return;openDrawer(`<div class="drawer-head"><div><h2 id="drawer-title">${esc(file.name)}</h2><p class="rep-caption mono">${esc(file.path)}</p></div>${btn('','drawer-close',{cls:'icon ghost',icon:'x',data:'aria-label="Закрыть просмотр файла"'})}</div><div class="drawer-body rm-preview">${rmCode(file)}<p class="rm-context-note">Данные фрагмента индекса · HEAD ${RM_SNAPSHOT.head} · демо.</p></div>`);},
  'rm-reference':(value) => {const [id,index]=value.split('|'),s=SYMBOLS[Number(id)],ref=s?.used[Number(index)];if(!ref || S.empty) return;const match=ref.match(/([a-zA-Z0-9_./-]+\.(?:rs|py)):(\d+)/),file=match && rmFiles().find((f) => f.path === match[1] || `${s.mod}/${match[1]}` === f.path);openDrawer(`<div class="drawer-head"><h2 id="drawer-title">Место использования</h2>${btn('','drawer-close',{cls:'icon ghost',icon:'x',data:'aria-label="Закрыть место использования"'})}</div><div class="drawer-body rm-preview"><p class="rm-reference-text mono">${esc(ref)}</p><p class="rep-caption">Символ: ${esc(s.n)}</p><p class="rm-context-note">Код места использования не передан. Ссылка показывает расположение из снимка.</p>${file ? btn('Открыть файл','rm-reference-file:'+file.path+'|'+match[2],{cls:'sm',icon:'file'}) : ''}</div>`);},
  'rm-reference-file':(value) => {const [path,line]=value.split('|');closeDrawer();rmChooseFile(path,Number(line));},
  'rm-copy':async (value) => {try{await navigator.clipboard.writeText(value);toast('Скопировано');}catch{toast('Не удалось скопировать. Выделите текст вручную.');}},
  'rm-export':() => {if(S.empty) return;const view=S.repo.tab,data=rmData(),items=view === 'symbols' ? data.symbols : view === 'links' ? data.links : data.files;if(!items.length) return;const value={demo:true,scope:'fragment',snapshot:RM_SNAPSHOT,view,filters:{q:S.repo.q,module:S.repo.mod,kind:S.repo.kind,relationType:S.repo.relType},items};const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='repo-map-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Экспортировано записей: ${items.length}`);},
});

/* ---------- Настройки ---------- */
const CFG_DOCS=[['project','project.json'],['orch','orchestration.json']];
const CFG_GROUP_NAMES=['Проект','Оркестрация','QA','Запуски','Хуки'];
const CFG_FIELDS=[
  {id:'name',group:0,label:'Имя проекта',doc:'project',path:['name'],type:'text',help:'Используется в заголовках и отчётах.'},
  {id:'tracker',group:0,label:'Трекер',doc:'project',path:['tracker'],type:'select',options:['github','gitlab','local'],help:'Источник задач и платформа публикации.'},
  {id:'stale',group:1,label:'Порог «нет сигнала»',doc:'orch',path:['stale_seconds'],type:'number',unit:'сек',help:'Положительное целое число. После этого времени запуск считается устаревшим.'},
  {id:'approval',group:1,label:'Подтверждение публикации',doc:'orch',path:['approval'],readonly:true,help:'Режим human: создание PR подтверждает человек.'},
  {id:'qa_cmd',group:2,label:'Команда полного QA',doc:'project',path:['qa','command'],type:'text',help:'Команда сохраняется как текст. Редактирование настройки не запускает проверку.'},
  {id:'parallel',group:3,label:'Параллельных запусков',doc:'orch',path:['parallel'],type:'number',unit:'worker',help:'Положительное целое число. Лимит одновременных worker.'},
  {id:'hook_meta',group:4,label:'Метаданные коммитов',readonly:true,value:'project-only',help:'Отклоняет подписи ассистентов. Значение из снимка hook-policy.json; файл не передан.'},
];
function cfgModel(){
  const c=S.cfg;if(!c.texts){c.texts={project:CFG_FILES['project.json'],orch:CFG_FILES['orchestration.json']};c.saved={...c.texts};c.versions=[{id:1,time:'22:01 · снимок',title:'Исходный демо-снимок',texts:{...c.saved}}];c.historyId=1;}c.q ||= '';return c;
}
const cfgGet=(doc,path) => path.reduce((o,k)=>o && typeof o === 'object' ? o[k] : undefined,doc);
function cfgParse(){const c=cfgModel(),docs={},errors=[];for(const [key,name] of CFG_DOCS){try{const d=JSON.parse(c.texts[key]);if(!d || Array.isArray(d) || typeof d !== 'object')throw new Error('Ожидается JSON-объект');docs[key]=d;}catch(e){errors.push({doc:key,path:'JSON',text:`${name}: ${e.message}`});}}
  const add=(doc,path,text)=>errors.push({doc,path,text});
  if(docs.project){const d=docs.project;if(typeof d.name !== 'string' || !d.name.trim())add('project','name','Имя проекта не должно быть пустым.');if(!['github','gitlab','local'].includes(d.tracker))add('project','tracker','Трекер: github, gitlab или local.');if(typeof d.qa?.command !== 'string' || !d.qa.command.trim())add('project','qa.command','Нужна непустая команда QA.');if(d.branch_pattern !== undefined && (typeof d.branch_pattern !== 'string' || !d.branch_pattern.trim()))add('project','branch_pattern','Шаблон ветки должен быть непустой строкой.');}
  if(docs.orch){const d=docs.orch;for(const key of ['stale_seconds','parallel'])if(!Number.isInteger(d[key]) || d[key]<1)add('orch',key,key === 'parallel' ? 'Число worker должно быть целым и больше нуля.' : 'Порог должен быть целым числом секунд больше нуля.');if(d.approval !== 'human')add('orch','approval','В этом макете публикация требует режима human.');if(!Array.isArray(d.roles) || !d.roles.length || d.roles.some((v)=>typeof v !== 'string' || !v.trim()))add('orch','roles','Роли должны быть непустым списком строк.');}
  return {docs,errors};
}
function cfgFlat(value,prefix='',out={}){if(value && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length){for(const [k,v] of Object.entries(value))cfgFlat(v,prefix ? prefix+'.'+k : k,out);}else out[prefix]=JSON.stringify(value);return out;}
function cfgDiff(before=cfgModel().saved,after=cfgModel().texts){const changes=[];for(const [key,file] of CFG_DOCS){if(before[key] === after[key])continue;try{const a=cfgFlat(JSON.parse(before[key])),b=cfgFlat(JSON.parse(after[key]));for(const path of new Set([...Object.keys(a),...Object.keys(b)]))if(a[path] !== b[path])changes.push({key,file,path,before:a[path],after:b[path]});if(JSON.stringify(a) === JSON.stringify(b))changes.push({key,file,path:'Форматирование JSON',before:'Исходный текст',after:'Изменено форматирование'});}catch{changes.push({key,file,path:'JSON',before:before[key],after:after[key]});}}return changes;}
const cfgCanEdit=()=>!S.empty && S.conn === 'online';
const cfgName=(key)=>CFG_DOCS.find(([id])=>id===key)?.[1] || 'hook-policy.json';
const cfgValue=(f,parsed=cfgParse())=>f.doc ? cfgGet(parsed.docs[f.doc],f.path) : f.value;
const cfgDisplay=(value)=>value === undefined ? 'Не передано' : typeof value === 'object' ? JSON.stringify(value) : String(value);
function cfgErrors(parsed){return parsed.errors.length ? `<ul class="cfg-errors" role="status">${parsed.errors.map((e)=>`<li>${ic('alert','sm')}<span>${esc(e.text)}</span></li>`).join('')}</ul>` : '<p class="cfg-valid" role="status">'+ic('check','sm')+' JSON и доступные параметры корректны.</p>';}
function cfgOverview(parsed){const changes=cfgDiff(),left=`<div class="ph"><h2>Файлы конфигурации</h2><span class="rep-caption">Черновик</span></div><ul class="cfg-file-list">${CFG_DOCS.map(([key,name])=>{const errs=parsed.errors.filter((e)=>e.doc===key),dirty=cfgModel().texts[key]!==cfgModel().saved[key];return `<li><button data-act="cfg-file:${key}">${repIcon(errs.length ? 'err' : 'ok',errs.length ? 'Есть ошибки' : 'Проверка пройдена')}<span><b class="mono">${name}</b><small>${errs.length ? errs.length+' '+plural(errs.length,'ошибка','ошибки','ошибок') : 'JSON и доступные параметры корректны'}</small></span>${dirty ? '<span class="tag">Изменён</span>' : ic('chev','sm')}</button></li>`;}).join('')}<li class="cfg-readonly-file">${ic('shield','sm')}<span><b class="mono">hook-policy.json</b><small>standard · project-only · только снимок</small></span><span class="tag">Просмотр</span></li></ul><div class="cfg-overview-foot"><p>Полная схема проекта здесь не проверяется. Проверка относится к двум файлам и параметрам макета.</p>${btn('Параметры','cfg-view:wizard',{cls:'sm',icon:'sliders'})}</div>`;
  const policies=[['Порог без сигнала',cfgDisplay(parsed.docs.orch?.stale_seconds)+' с'],['Параллельные запуски',cfgDisplay(parsed.docs.orch?.parallel)],['Подтверждение',cfgDisplay(parsed.docs.orch?.approval)],['Команда QA',cfgDisplay(parsed.docs.project?.qa?.command)]];
  const right=harSection('Параметры процесса',harFacts(policies)+`<div class="cfg-info">${ic(changes.length ? 'edit' : 'check','sm')}<div><b>${changes.length ? changes.length+' '+plural(changes.length,'изменение','изменения','изменений')+' в черновике' : 'Черновик совпадает с сохранённой версией'}</b><p>${changes.length ? 'Перед сохранением проверьте значения и список изменений.' : 'Можно редактировать параметры или открыть JSON.'}</p></div></div><div class="har-actions">${btn('Проверить изменения','cfg-view:changes',{cls:'sm',icon:'eye',dis:!changes.length})}${btn('История версий','cfg-view:history',{cls:'sm',icon:'clock'})}</div>`);
  return `<div class="panel cfg-pair">${left.startsWith('<section') ? left : '<section>'+left+'</section>'}<section>${right}${cfgAdviceDigest()}</section></div>`;
}
function cfgParameters(parsed){const c=cfgModel(),changes=cfgDiff();let list=CFG_FIELDS.filter((f)=>(!c.q.trim() || `${f.label} ${f.id} ${f.path?.join('.')} ${f.help} ${cfgDisplay(cfgValue(f,parsed))}`.toLowerCase().includes(c.q.trim().toLowerCase())) && (!c.changedOnly || changes.some((x)=>x.key===f.doc && x.path===f.path?.join('.'))));const groups=CFG_GROUP_NAMES.map((name,id)=>({name,id,fields:list.filter((f)=>f.group===id)})).filter((g)=>g.fields.length);const group=groups.find((g)=>g.id===Number(c.group)) || groups[0];if(group)c.group=group.id;const sel=group ? cfgSelected(group) : null;
  const tools=`<div class="panel cfg-tools">${search('cfg.q',c.q,'Поиск параметра или ключа')}${btn('Изменённые · '+changes.length,'cfg-toggle-changed',{cls:'sm'+(c.changedOnly ? ' primary' : ''),data:`aria-pressed="${!!c.changedOnly}"`})}${btn('Сбросить','cfg-search-reset',{cls:'sm ghost',dis:!c.q && !c.changedOnly})}</div>`;
  if(!group)return tools+`<section class="panel cfg-empty">${empty('Параметры не найдены','Измените запрос или отключите фильтр изменений.',btn('Сбросить фильтры','cfg-search-reset',{cls:'sm'}))}</section>`;
  const left=`<aside class="panel cfg-groups" aria-label="Группы настроек"><div class="ph"><h2>Группы · ${groups.length}</h2></div><nav>${groups.map((g)=>`<button data-act="cfg-group:${g.id}" class="${g.id===group.id ? 'selected' : ''}" aria-pressed="${g.id===group.id}"><span>${g.name}</span><b>${g.fields.length}</b></button>`).join('')}</nav><p class="cfg-list-note">${list.length} из ${CFG_FIELDS.length} параметров</p></aside>`;
  const fields=group.fields.map((f)=>{const value=cfgValue(f,parsed),err=parsed.errors.find((e)=>e.doc===f.doc && (e.path===f.path?.join('.') || e.path==='JSON')),dirty=changes.some((x)=>x.key===f.doc && x.path===f.path?.join('.')),disabled=!cfgCanEdit() || !parsed.docs[f.doc];const attrs=`data-cfg-field="${f.id}" aria-label="${esc(f.label)}" ${err ? `aria-invalid="true" aria-describedby="cfg-error-${f.id}"` : ''} ${disabled ? 'disabled' : ''}`;return `<div class="cfg-param${sel?.id===f.id ? ' selected' : ''}"><div class="cfg-param-heading">${f.readonly ? `<b>${f.label}</b>` : `<label for="cfg-value-${f.id}">${f.label}</label>`}${dirty ? '<span class="tag">Изменён</span>' : ''}${f.readonly ? '<span class="cfg-lock" title="Значение только для просмотра">'+ic('lock','sm')+'</span>' : cfgPickBtn(f,sel)}</div>${f.readonly ? `<div class="cfg-readonly-value mono" aria-label="${esc(f.label)}">${esc(cfgDisplay(value))}</div>` : `<div class="cfg-input">${f.type === 'select' ? `<select id="cfg-value-${f.id}" ${attrs}>${f.options.includes(value) ? '' : '<option value="">Выберите значение</option>'}${f.options.map((v)=>`<option ${v===value ? 'selected' : ''}>${v}</option>`).join('')}</select>` : `<input id="cfg-value-${f.id}" type="${f.type}" value="${esc(value === undefined ? '' : value)}" ${f.type==='number' ? 'min="1" step="1"' : ''} ${attrs}>`}${f.unit ? '<span>'+f.unit+'</span>' : ''}</div>`}<p>${f.help}</p>${cfgRecRow(f,value)}${err ? `<div class="cfg-field-error" id="cfg-error-${f.id}" role="status">${esc(err.text)}</div>` : ''}<small class="mono">${cfgName(f.doc)}${f.path ? ' · '+f.path.join('.') : ''}</small></div>`;}).join('');
  const right=`<section class="panel cfg-param-detail" aria-label="Группа ${group.name}"><div class="ph"><h2>${group.name}</h2><span class="rep-caption">${group.fields.length} ${plural(group.fields.length,'параметр','параметра','параметров')}</span></div><div>${fields}</div><div class="cfg-param-foot"><span>Общий черновик с JSON-редактором</span>${btn('Открыть JSON','cfg-file:'+(group.fields.find((f)=>f.doc)?.doc || 'project'),{cls:'sm',icon:'file'})}</div></section>`;
  return tools+`<div class="cfg-workspace cfg-wiz">${left}${right}${cfgAiPanel(sel,parsed)}</div>`;
}
function cfgJson(parsed){const c=cfgModel();c.fileKey ||= 'project';const key=c.fileKey,name=cfgName(key),errors=parsed.errors.filter((e)=>e.doc===key);
  const left=`<aside class="panel cfg-json-files" aria-label="Файлы настроек"><div class="ph"><h2>JSON · ${CFG_DOCS.length}</h2></div>${CFG_DOCS.map(([id,file])=>`<button class="${id===key ? 'selected' : ''}" data-act="cfg-file:${id}" aria-pressed="${id===key}">${repIcon(parsed.errors.some((e)=>e.doc===id) ? 'err' : 'ok')}<span><b class="mono">${file}</b><small>${c.texts[id]===c.saved[id] ? 'Без изменений' : 'Изменён в черновике'}</small></span></button>`).join('')}<div class="cfg-json-note">JSON и форма используют одни данные. Неизвестные поля сохраняются.</div></aside>`;
  const right=`<section class="panel cfg-editor-panel"><div class="ph"><h2 class="mono">${name}</h2>${pill(errors.length ? 'err' : 'ok',errors.length ? 'Есть ошибки' : 'Проверен в макете')}</div><label class="sr" for="cfg-json-editor">Редактор ${name}</label><textarea id="cfg-json-editor" class="cfg-json-editor" data-bind="cfg.texts.${key}" spellcheck="false" ${!cfgCanEdit() ? 'readonly' : ''}>${esc(c.texts[key])}</textarea><div class="cfg-json-result">${cfgErrors({errors})}</div><div class="cfg-param-foot"><span>Проверка синтаксиса и доступных параметров</span><div>${btn('Форматировать','cfg-format',{cls:'sm',dis:!cfgCanEdit() || !parsed.docs[key]})}${btn('Проверить изменения','cfg-view:changes',{cls:'sm primary',dis:!cfgDiff().length})}</div></div></section>`;
  return `<div class="cfg-workspace cfg-json-workspace">${left}${right}</div>`;
}
function cfgChangeRows(changes){return changes.length ? `<div class="cfg-diff-table"><div class="cfg-diff-head"><span>Параметр</span><span>Было</span><span>Станет</span></div>${changes.map((x)=>`<div class="cfg-diff-row"><span><b class="mono">${esc(x.path)}</b><small>${x.file}</small></span><pre class="cfg-before">${esc(x.before ?? 'Не задано')}</pre><pre class="cfg-after">${esc(x.after ?? 'Удалено')}</pre></div>`).join('')}</div>` : '<div class="cfg-no-changes">'+ic('check')+'<div><h3>Изменений нет</h3><p>Черновик совпадает с сохранённой версией.</p></div></div>';}
function cfgChanges(parsed){const changes=cfgDiff(),canSave=cfgCanEdit() && changes.length>0 && !parsed.errors.length;
  return `<section class="panel cfg-changes"><div class="ph"><h2>Изменения · ${changes.length}</h2><span class="rep-caption">Сравнение с v${cfgModel().versions.at(-1).id}</span></div>${cfgChangeRows(changes)}<div class="cfg-review-validation">${cfgErrors(parsed)}<p>Сохраняется локальная версия макета. Файлы проекта и runtime не меняются; полная схема не проверяется.</p></div><div class="cfg-review-foot">${btn('Отменить правки','cfg-discard',{cls:'sm',dis:!cfgCanEdit() || !changes.length})}${btn('Сохранить версию в макете','cfg-save',{cls:'sm primary',icon:'check',dis:!canSave})}</div></section>`;
}
function cfgSnapshots(version){return `<div class="cfg-snap">${CFG_DOCS.map(([key,name])=>`<figure><figcaption class="mono">${name}</figcaption><pre class="mono">${esc(version.texts[key])}</pre></figure>`).join('')}</div>`;}
function cfgHistory(){const c=cfgModel(),version=c.versions.find((v)=>String(v.id)===String(c.historyId)) || c.versions.at(-1),index=c.versions.indexOf(version),previous=c.versions[index-1];c.historyId=version.id;
  const left=`<aside class="panel cfg-history-list"><div class="ph"><h2>Версии · ${c.versions.length}</h2></div>${[...c.versions].reverse().map((v)=>`<button class="${v.id===version.id ? 'selected' : ''}" data-act="cfg-history:${v.id}" aria-pressed="${v.id===version.id}"><span class="cfg-version-dot">${v.id}</span><span><b>${esc(v.title)}</b><small>${v.time}${v.id===c.versions.at(-1).id ? ' · текущая' : ''}</small></span></button>`).join('')}</aside>`;
  const right=`<section class="panel cfg-history-detail"><div class="ph"><h2>Версия v${version.id}</h2><span class="rep-caption">${version.time}</span></div>${previous ? cfgChangeRows(cfgDiff(previous.texts,version.texts)) : `<div class="har-pad">${harFacts([['Источник','Исходный демо-снимок'],['project.json','Передан'],['orchestration.json','Передан']])}<p class="cfg-history-note">Более ранние версии и содержимое прежних файлов не переданы.</p></div>`}${cfgSnapshots(version)}<div class="cfg-param-foot"><span>История хранится до перезагрузки</span>${btn('Загрузить в черновик','cfg-restore:'+version.id,{cls:'sm',icon:'refresh',dis:!cfgCanEdit() || CFG_DOCS.every(([key])=>c.texts[key]===version.texts[key])})}</div></section>`;
  return `<div class="cfg-workspace cfg-history-workspace">${left}${right}</div>`;
}
screens.configuration=()=>{const c=cfgModel();if(CFG_DOCS.some(([,name])=>name===c.tab)){c.fileKey=CFG_DOCS.find(([,name])=>name===c.tab)[0];c.tab='json';}const view=['overview','wizard','json','changes','history'].includes(c.tab) ? c.tab : 'overview',parsed=cfgParse(),changes=cfgDiff(),latest=c.versions.at(-1);
  const summary=`<section class="panel cfg-summary" aria-label="Сводка настроек"><div class="cfg-metrics">${[['JSON-файлы',S.empty ? '—' : CFG_DOCS.length],['Параметры',S.empty ? '—' : CFG_FIELDS.length],['Изменения',S.empty ? '—' : changes.length],['Версия в макете',S.empty ? '—' : 'v'+latest.id]].map(([name,value])=>`<div><span>${name}</span><b>${value}</b></div>`).join('')}</div><div class="cfg-summary-foot"><span class="${!S.empty && parsed.errors.length ? 'err' : ''}">${ic(S.empty ? 'dot' : parsed.errors.length ? 'alert' : 'check','sm')} ${S.empty ? 'Нет данных' : parsed.errors.length ? parsed.errors.length+' '+plural(parsed.errors.length,'ошибка','ошибки','ошибок') : 'JSON и доступные параметры корректны'}</span><span>${S.empty ? 'Проект не выбран' : S.conn==='reconnect' ? 'Кэш 22:01 · устарел' : 'Локальный демо-черновик'}</span><span>Файлы проекта не изменяются</span></div></section>`;
  const nav=`<div class="cfg-tabs">${pipeTabs('cfg.tab',[['overview','Обзор','1'],['wizard','Параметры',CFG_FIELDS.length],['json','JSON',ic('file','sm')],['changes','Изменения',S.empty ? '—' : changes.length],['history','История',S.empty ? '—' : c.versions.length]],view)}</div>`;
  const content=S.empty ? `<section class="panel cfg-empty">${empty('Настройки проекта не переданы','Откройте проект, чтобы выбрать и проверить конфигурацию.',btn('Открыть проект','go:open-project',{cls:'sm primary',icon:'project'}))}</section>` : {overview:cfgOverview,wizard:cfgParameters,json:cfgJson,changes:cfgChanges,history:cfgHistory}[view](parsed);
  return `<div class="page configuration-screen fit">${head('Настройки','Параметры проекта, JSON и история изменений.',btn('Экспорт черновика','cfg-export',{cls:'sm',icon:'file',dis:S.empty || !!parsed.errors.length})+btn('','cfg-refresh',{cls:'icon',icon:'refresh',dis:!cfgCanEdit(),title:'Обновить снимок настроек',data:'aria-label="Обновить снимок настроек"'}))}${summary}${nav}${content}</div>`.replaceAll('data-act="set"','data-act="cfg-set"');
};
Object.assign(actions,{
  'cfg-set':(_,el)=>{const key=el.dataset.k,value=el.dataset.v;setPath(key,value);render();const target=$(`[data-k="${key}"][data-v="${value}"]`);if(target)target.focus();},
  'cfg-view':(tab)=>{S.cfg.tab=tab;render();},
  'cfg-file':(key)=>{if(!CFG_DOCS.some(([id])=>id===key))return;Object.assign(S.cfg,{tab:'json',fileKey:key});render();},
  'cfg-group':(id)=>{S.cfg.group=Number(id);render();const target=$(`[data-act="cfg-group:${id}"]`);if(target)target.focus();},
  'cfg-search-reset':()=>{Object.assign(S.cfg,{q:'',changedOnly:false});render();},
  'cfg-toggle-changed':()=>{S.cfg.changedOnly=!S.cfg.changedOnly;render();},
  'cfg-format':()=>{const c=cfgModel(),key=c.fileKey,doc=cfgParse().docs[key];if(!cfgCanEdit() || !doc)return;c.texts[key]=JSON.stringify(doc,null,2);render();},
  'cfg-save':()=>{const c=cfgModel(),parsed=cfgParse(),changes=cfgDiff();if(!cfgCanEdit() || parsed.errors.length || !changes.length)return;c.saved={...c.texts};const id=c.versions.at(-1).id+1;c.versions.push({id,time:new Date().toLocaleTimeString('ru-RU'),title:`Сохранено ${changes.length} ${plural(changes.length,'изменение','изменения','изменений')}`,texts:{...c.texts}});c.historyId=id;render();toast('Версия v'+id+' сохранена в памяти макета');},
  'cfg-discard':()=>{if(!cfgCanEdit() || !cfgDiff().length)return;dialog('<h2 id="dlg-title">Отменить правки черновика?</h2><p>Черновик вернётся к последней сохранённой версии макета.</p>',()=>{S.cfg.texts={...cfgModel().saved};render();},'Отменить правки');},
  'cfg-history':(id)=>{S.cfg.historyId=Number(id);render();const target=$(`[data-act="cfg-history:${id}"]`);if(target)target.focus();},
  'cfg-restore':(id)=>{const version=cfgModel().versions.find((v)=>String(v.id)===id);if(!cfgCanEdit() || !version)return;dialog(`<h2 id="dlg-title">Загрузить v${version.id} в черновик?</h2><p>${cfgDiff().length ? 'Текущие несохранённые правки будут заменены. ' : ''}После загрузки можно проверить различия и сохранить новую локальную версию.</p>`,()=>{if(!cfgCanEdit())return;S.cfg.texts={...version.texts};S.cfg.tab='changes';render();},'Загрузить');},
  'cfg-refresh':()=>{if(!cfgCanEdit())return;render();toast('Демо-снимок обновлён; текущие правки остаются в черновике.');},
  'cfg-export':()=>{const parsed=cfgParse();if(S.empty || parsed.errors.length)return;const value={demo:true,scope:'draft',version:cfgModel().versions.at(-1).id,files:Object.fromEntries(CFG_DOCS.map(([key,name])=>[name,parsed.docs[key]]))};const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='configuration-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Черновик экспортирован');},
});
document.addEventListener('input',(event)=>{const el=event.target,id=el.dataset?.cfgField;if(!id || !cfgCanEdit())return;const f=CFG_FIELDS.find((f)=>f.id===id),parsed=cfgParse();if(!f || f.readonly || !parsed.docs[f.doc])return;const raw=el.value,value=f.type==='number' && raw!=='' ? Number(raw) : raw,doc=parsed.docs[f.doc];let parent=doc;for(const key of f.path.slice(0,-1)){if(!parent[key] || typeof parent[key] !== 'object' || Array.isArray(parent[key]))parent[key]={};parent=parent[key];}parent[f.path.at(-1)]=value;const pos=el.selectionStart;S.cfg.texts[f.doc]=JSON.stringify(doc,null,2);render();const next=$(`[data-cfg-field="${id}"]`);if(next){next.focus();if(typeof pos==='number')try{next.setSelectionRange(pos,pos);}catch{}}});
